-- Read-only catalog metadata. No business rows, function bodies, secrets or writes returned.
-- Execute separately in each project; this file is not an application migration.
select p.proname as name, pg_catalog.pg_get_function_identity_arguments(p.oid) as arguments, md5(p.prosrc) as source_md5, md5(btrim(replace(p.prosrc,E'\r\n',E'\n'),E' \t\r\n')) as source_lf_boundary_trimmed_md5, length(p.prosrc) as source_length, md5(pg_catalog.pg_get_expr(p.proargdefaults,0)) as defaults_md5, md5(array_to_string(p.proconfig,E'\n')) as configuration_md5, (select jsonb_agg(split_part(setting,'=',1) order by split_part(setting,'=',1)) from unnest(p.proconfig) setting) as configuration_names, l.lanname as language, p.proisstrict as strict, p.prosecdef as security_definer, p.proleakproof as leakproof, p.proparallel as parallel, p.provolatile as volatility, p.procost as cost, p.prorows as rows, pg_catalog.pg_get_userbyid(p.proowner) as owner from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid=p.pronamespace join pg_catalog.pg_language l on l.oid=p.prolang where n.nspname='public' and p.proname in ('get_random_exercise','get_monthly_leaderboard','get_weekly_leaderboard') order by p.proname,pg_catalog.pg_get_function_identity_arguments(p.oid);
